import socket# from lib.utility.util import chessboardfrom lib.classDir.class_file import pieces, chessboardimport sysip_addr = sys.argv[1]pos_initial = sys.argv[2]nxt_pos = sys.argv[3]client_s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)pos_initial_tosend = bytes(pos_initial, 'utf-8')nxt_pos_tosend = bytes(nxt_pos, 'utf-8')print(ip_addr)client_s.sendto(pos_initial_tosend, (ip_addr, 12345))client_s.sendto(nxt_pos_tosend, (ip_addr, 12345))while True:    client_s.settimeout(1)    try:        recvpack, payload = client_s.recvfrom(4096)    except socket.timeout:        recvpack = None    if recvpack is not None:        data, addr = client_s.recvfrom(4096)        pos_initial_received = data.decode() # attention list version str        data, addr = client_s.recvfrom(4096)        nxt_pos_received = data.decode()        breakclient_s.close()'''while True:    client_s.sendto(bytes('toto', 'utf-8'), ('192.168.0.15', 12345))    client_s.settimeout(1)    try:        recvpack, payload = client_s.recvfrom(4096)    except socket.timeout:        recvpack = None    if recvpack is not None:        data, addr = client_s.recvfrom(4096)        chessboard_received = eval(data)        chessboard = chessboard_received        print(chessboard)        data, addr = client_s.recvfrom(4096)        isit_true_false = bool(data.decode())        if isit_true_false == True:            client_s.close()    else:        if has_played == True:            has_played = False            chessboard_tosend = bytes(str(chessboard), 'utf-8')            true_false = bytes(str(False), 'utf-8')            client_s.sendto(chessboard_tosend, (ip_addr, 12345))            client_s.sendto(true_false, (ip_addr, 12345))'''